export interface Category {
  id: string;
  name: string;
  description: string;
  icon?: string;
}

export interface Tool {
  id: string; // Unique identifier (usually same as slug)
  title: string;
  description: string;
  slug: string; // e.g., 'cgpa-to-percentage'
  category: string;
  subcategory?: string;
  icon: string;
  keywords?: string[];
  popular?: boolean;
  featured?: boolean;
  seoTitle?: string;
  seoDescription?: string;
  component?: string;
  formulaConfig?: {
    inputs: { id: string; label: string; placeholder?: string; type?: string }[];
    expression: string; // JavaScript math expression, variables match input ids
    outputLabel: string;
    outputUnit?: string;
  };
  medicalDisclaimer?: boolean;
  aliases?: string[];
  related?: string[];
}

